seed.bin/crontab:
#!/bin/sh
store="${XPST_CRONTAB_STORE:-/nonexistent}"
case "$1" in
  -l) [ -f "$store" ] || { echo "no crontab for the fixture" >&2; exit 1; }; cat "$store" ;;
  -) sed -E 's#^(\*/[0-9]+ \* \* \* \* )[^ ]+( serve >> )#\1<ENGINE>\2#' > "$store" ;;
  -r) rm -f "$store" ;;
  *) echo "unsupported: $*" >&2; exit 2 ;;
esac

